            color: #c9a961;
            margin-bottom: 20px;
            padding-bottom: 15px;
            border-bottom: 2px solid #444;
        }

        .header h1 {
            font-size: 28px;
            margin: 0;
            text-shadow: 0 2px 4px rgba(0,0,0,0.8);
            letter-spacing: 2px;
        }

        .header p {
            font-size: 14px;
            color: #8b7355;
            margin: 5px 0 0 0;
        }

        /* 分页系统 */
        .page {
            display: none;
            animation: fadeIn 0.3s ease;
        }

        .page.active {
            display: block;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* 进度指示器 */
        .progress-bar {
            display: flex;
            justify-content: center;
            margin-bottom: 25px;
            gap: 20px;
            position: relative;
            flex-wrap: wrap;
        }

        .progress-bar::before {
            content: '';
            position: absolute;
            top: 15px;
            left: 10%;
            right: 10%;
            height: 2px;
            background: #333;
            z-index: 0;
        }

        .progress-step {
            position: relative;
            z-index: 1;
            text-align: center;
        }

        .progress-dot {
            width: 30px;
            height: 30px;
            background: #333;
            border: 2px solid #444;
            border-radius: 50%;
            margin: 0 auto 5px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            color: #666;
            transition: all 0.3s ease;
        }

        .progress-step.active .progress-dot {
            background: #c9a961;
            border-color: #c9a961;
            color: #1a1a1a;
            box-shadow: 0 0 10px rgba(201,169,97,0.5);
        }

        .progress-step.completed .progress-dot {
            background: #8b7355;
            border-color: #8b7355;
            color: #1a1a1a;
        }

        .progress-label {
            font-size: 11px;
            color: #666;
            max-width: 60px;
        }

        .progress-step.active .progress-label,
        .progress-step.completed .progress-label {
            color: #c9a961;
        }

        /* 页面导航 */
        .page-nav {
            display: flex;
            justify-content: space-between;
            margin-top: 25px;
            padding-top: 15px;
            border-top: 1px solid #444;
            gap: 15px;
        }

        .page-button {
            padding: 12px 30px;
            background: linear-gradient(135deg, #c9a961, #8b7355);
            border: 1px solid #444;
            border-radius: 8px;
            cursor: pointer;
            font-family: inherit;
            color: #1a1a1a;
            transition: all 0.2s ease;
            font-size: 14px;
            font-weight: bold;
            text-shadow: 0 1px 2px rgba(0,0,0,0.3);
            flex: 1;
            max-width: 200px;
        }

        .page-button:hover {
            transform: translateY(-2px);
            box-shadow: 0 5px 15px rgba(201,169,97,0.3);
        }

        .page-button:active {
            transform: translateY(0);
        }

        .page-button:disabled {
            opacity: 0.5;
            cursor: not-allowed;
            transform: none;
        }

        /* 世界观内容样式 */
        .lore-content {
            background: rgba(0,0,0,0.6);
            border: 1px solid #444;
            border-radius: 10px;
            padding: 20px;
            margin-bottom: 20px;
            max-height: 500px;
            overflow-y: auto;
            line-height: 1.8;
        }

        .lore-content::-webkit-scrollbar {
            width: 8px;
        }

        .lore-content::-webkit-scrollbar-track {
            background: rgba(0,0,0,0.3);
            border-radius: 4px;
        }

        .lore-content::-webkit-scrollbar-thumb {
            background: #444;
            border-radius: 4px;
        }

        .lore-content h2 {
            color: #c9a961;
            font-size: 20px;
            margin: 20px 0 10px 0;
            padding-bottom: 5px;
            border-bottom: 1px solid #444;
        }

        .lore-content h3 {
            color: #8b7355;
            font-size: 16px;
            margin: 15px 0 8px 0;
        }

        .lore-content p {
            color: #999;
            margin: 10px 0;
            text-align: justify;
        }

        .lore-content ul {
            color: #999;
            padding-left: 20px;
        }

        .lore-content li {
            margin: 5px 0;
        }

        .lore-content strong {
            color: #c9a961;
        }

        /* 种族选择样式 */
        .race-grid {
            display: grid;
            grid-template-columns: 1fr;
            gap: 12px;
            margin-bottom: 20px;
            max-height: 450px;
            overflow-y: auto;
            padding-right: 5px;
        }

        .race-grid::-webkit-scrollbar {
            width: 8px;
        }

        .race-grid::-webkit-scrollbar-track {
            background: rgba(0,0,0,0.3);
            border-radius: 4px;
        }

        .race-grid::-webkit-scrollbar-thumb {
            background: #444;
            border-radius: 4px;
        }

        .race-item {
            border: 1px solid #444;
            border-radius: 10px;
            background: rgba(0,0,0,0.6);
            padding: 15px;
            transition: all 0.3s ease;
            cursor: pointer;
            position: relative;
            overflow: hidden;
        }

        .race-item::before {
            content: '';
            position: absolute;
            top: 0;
            left: -100%;
            width: 100%;
            height: 100%;
            background: linear-gradient(90deg, transparent, rgba(201,169,97,0.2), transparent);
            transition: left 0.5s ease;
        }

        .race-item:hover::before {
            left: 100%;
        }

        .race-item:hover {
            border-color: #c9a961;
            transform: translateY(-2px);
            box-shadow: 0 5px 15px rgba(201,169,97,0.2);
        }

        .race-item.active {
            background: rgba(201,169,97,0.1);
            border-color: #c9a961;
            box-shadow: 0 0 20px rgba(201,169,97,0.3);
        }

        .race-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 10px;
        }

        .race-name {
            font-size: 18px;
            color: #c9a961;
            font-weight: bold;
        }

        .race-points {
            background: #444;
            color: #c9a961;
            padding: 4px 12px;
            border-radius: 15px;
            font-size: 14px;
            font-weight: bold;
        }

        .race-desc {
            color: #999;
            line-height: 1.6;
            font-size: 14px;
            margin-bottom: 10px;
        }

        .race-bonus {
            display: flex;
            gap: 10px;
            flex-wrap: wrap;
            margin-top: 10px;
            padding-top: 10px;
            border-top: 1px dashed #333;
        }

        .bonus-tag {
            background: rgba(201,169,97,0.2);
            color: #c9a961;
            padding: 3px 10px;
            border-radius: 12px;
            font-size: 12px;
            border: 1px solid #444;
        }

        .bonus-tag.negative {
            background: rgba(220,20,60,0.2);
            color: #dc143c;
            border-color: #5a3333;
        }

        /* 势力选择样式 */
        .faction-grid {
            display: grid;
            grid-template-columns: 1fr;
            gap: 12px;
            margin-bottom: 20px;
        }

        .faction-item {
            border: 1px solid #444;
            border-radius: 10px;
            background: rgba(0,0,0,0.6);
            padding: 15px;
            transition: all 0.3s ease;
            cursor: pointer;
        }

        .faction-item:hover {
            border-color: #c9a961;
            transform: translateY(-2px);
            box-shadow: 0 5px 15px rgba(201,169,97,0.2);
        }

        .faction-item.active {
            background: rgba(201,169,97,0.1);
            border-color: #c9a961;
        }

        .faction-name {
            font-size: 16px;
            color: #c9a961;
            font-weight: bold;
            margin-bottom: 5px;
        }

        .faction-desc {
            color: #999;
            font-size: 13px;
            line-height: 1.5;
        }

        /* 自定义势力输入 */
        .custom-faction {
            margin-top: 20px;
            padding: 15px;
            background: rgba(0,0,0,0.6);
            border: 1px solid #444;
            border-radius: 10px;
        }

        .custom-faction-title {
            color: #c9a961;
            font-size: 16px;
            margin-bottom: 10px;
        }

        .custom-faction-input {
            width: 100%;
            padding: 10px;
            background: rgba(0,0,0,0.6);
            border: 1px solid #444;
            border-radius: 6px;
            color: #c9a961;
            font-family: inherit;
            font-size: 14px;
        }

        /* 属性分配样式 */
        .points-display {
            background: rgba(201,169,97,0.1);
            border: 2px solid #444;
            border-radius: 10px;
            padding: 15px;
            text-align: center;
            margin-bottom: 20px;
        }

        .points-value {
            font-size: 36px;
            color: #c9a961;
            font-weight: bold;
            text-shadow: 0 2px 4px rgba(0,0,0,0.8);
        }

        .points-label {
            font-size: 14px;
            color: #8b7355;
            margin-top: 5px;
        }

        /* 生命值显示样式 */
        .health-display {
            background: rgba(220,20,60,0.1);
            border: 2px solid #5a3333;
            border-radius: 10px;
            padding: 15px;
            text-align: center;
            margin-bottom: 20px;
        }

        .health-value {
            font-size: 36px;
            color: #dc143c;
            font-weight: bold;
            text-shadow: 0 2px 4px rgba(0,0,0,0.8);
        }

        .health-label {
            font-size: 14px;
            color: #8b7355;
            margin-top: 5px;
        }

        .health-formula {
            font-size: 12px;
            color: #999;
            margin-top: 5px;
        }

        .attr-info {
            background: rgba(0,0,0,0.6);
            border: 1px solid #444;
            border-radius: 10px;
            padding: 15px;
            margin-bottom: 20px;
        }

        .attr-info h3 {
            color: #c9a961;
            font-size: 16px;
            margin: 0 0 10px 0;
        }

        .attr-info ul {
            margin: 0;
            padding-left: 20px;
            color: #999;
            font-size: 14px;
            line-height: 1.8;
        }

        .attr-groups {
            display: grid;
            grid-template-columns: 1fr;
            gap: 15px;
            margin-bottom: 20px;
        }

        .attr-group {
            border: 1px solid #444;
            border-radius: 10px;
            padding: 15px;
            background: rgba(0,0,0,0.6);
        }

        .attr-title {
            text-align: center;
            font-size: 18px;
            color: #c9a961;
            margin-bottom: 10px;
            font-weight: bold;
        }

        .attr-value {
            text-align: center;
            font-size: 24px;
            color: #8b7355;
            margin-bottom: 10px;
            font-weight: bold;
        }

        .attr-buttons {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 8px;
        }

        .attr-button {
            padding: 12px 0;
            background: linear-gradient(135deg, #444, #333);
            border: 1px solid #555;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.2s ease;
            text-align: center;
            font-family: inherit;
            color: #c9a961;
            font-size: 14px;
            font-weight: bold;
        }

        .attr-button:hover:not(:disabled) {
            background: linear-gradient(135deg, #555, #444);
            transform: translateY(-2px);
            box-shadow: 0 5px 10px rgba(201,169,97,0.2);
        }

        .attr-button:active:not(:disabled) {
            transform: translateY(0);
        }

        .attr-button:disabled {
            opacity: 0.3;
            cursor: not-allowed;
        }

        /* 输出文本框 */
        .output-area {
            width: 100%;
            height: 150px;
            border: 1px solid #444;
            border-radius: 10px;
            padding: 15px;
            background: rgba(0,0,0,0.6);
            color: #c9a961;
            resize: vertical;
            font-family: inherit;
            font-size: 14px;
            line-height: 1.6;
            margin-bottom: 15px;
        }

        .control-buttons {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 10px;
            margin-bottom: 20px;
        }

        .control-button {
            padding: 10px 20px;
            background: linear-gradient(135deg, #444, #333);
            border: 1px solid #555;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.2s ease;
            font-family: inherit;
            color: #c9a961;
            font-size: 14px;
            font-weight: bold;
        }

        .control-button:hover {
            background: linear-gradient(135deg, #555, #444);
            transform: translateY(-2px);
            box-shadow: 0 5px 10px rgba(201,169,97,0.2);
        }

        .control-button:active {
            transform: translateY(0);
        }

        /* 通知提示 */
        .notification {
            position: fixed;
            bottom: 30px;
            left: 50%;
            transform: translateX(-50%);
            background: #1a1a1a;
            color: #c9a961;
            padding: 12px 24px;
            border-radius: 10px;
            border: 1px solid #444;
            box-shadow: 0 5px 20px rgba(0,0,0,0.8);
            z-index: 1000;
            opacity: 0;
            transition: opacity 0.3s ease;
            pointer-events: none;
            font-size: 14px;
        }

        .notification.show {
            opacity: 1;
        }

        /* 响应式设计 */
        @media (min-width: 600px) {
            .container {
                padding: 30px;
            }

            .race-grid {
                grid-template-columns: repeat(2, 1fr);
            }

            .attr-groups {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        @media (min-width: 768px) {
            .faction-grid {
                grid-template-columns: repeat(2, 1fr);
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <!-- 标题 -->
        <div class="header">
            <h1>饮歌镇角色创建</h1>
            <p>1920年代 · 蒸汽与神秘的时代</p>
        </div>

        <!-- 进度指示器 -->
        <div class="progress-bar">
            <div class="progress-step active" data-step="1">
                <div class="progress-dot">1</div>
                <div class="progress-label">世界观</div>
            </div>
            <div class="progress-step" data-step="2">
                <div class="progress-dot">2</div>
                <div class="progress-label">神秘学</div>
            </div>
            <div class="progress-step" data-step="3">
                <div class="progress-dot">3</div>
                <div class="progress-label">种族</div>
            </div>
            <div class="progress-step" data-step="4">
                <div class="progress-dot">4</div>
                <div class="progress-label">势力</div>
            </div>
            <div class="progress-step" data-step="5">
                <div class="progress-dot">5</div>
                <div class="progress-label">属性</div>
            </div>
        </div>

        <!-- 页面1: 世界观介绍 -->
        <div id="page-1" class="page active">
            <div class="lore-content">
                <h2>时代背景</h2>
                <p><strong>时间：</strong>1920年代初，蒸汽朋克与爵士乐的黄金时代</p>
                <p><strong>科技水平：</strong>电力初普及，汽车刚兴起，无线电广播开始流行，飞艇是主要远程交通工具</p>
                <p><strong>政治格局：</strong>刚结束一场世界大战，各国处于脆弱和平期，民族主义抬头</p>
                <p><strong>社会风貌：</strong>工业化带来繁荣假象，贫富差距扩大，都市化加速</p>
                <p><strong>文化特征：</strong>理性主义盛行，科学被视为进步象征，宗教影响力下降</p>
                <p><strong>守密组织：</strong>各国秘密部门负责掩盖真相，维持"正常"</p>

                <h2>英国社会文化潮流</h2>
                <p><strong>爵士文化：</strong>美国爵士乐传入上流社交场，年轻贵族在密室舞会中痴迷摇摆舞。传统保守派斥其为"堕落黑人音乐"。</p>
                <p><strong>时尚革新：</strong>女性抛弃维多利亚束身衣，改穿短裙露膝。男士西装剪裁愈发修身，礼帽成为身份象征。</p>
                <p><strong>科学崇拜：</strong>达尔文进化论与尼采超人学说融合，知识分子鼓吹"理性至上"。教会影响力急速衰退。</p>
                <p><strong>神秘主义：</strong>通灵会、降神术在中产阶级流行。战后创伤让人们渴望与亡者对话。</p>

                <h2>工业化的明暗</h2>
                <p><strong>光明面：</strong>铁路网连通全国，电报电话即时通讯。百货商场、电影院繁荣都市生活。医疗进步延长寿命。</p>
                <p><strong>黑暗面：</strong>煤烟笼罩天空终年不见阳光。工厂童工普遍，断肢工伤日常。贫民窟疾病横行，人均寿命不足四十。</p>

                <h2>普遍歧视</h2>
                <p><strong>种族等级：</strong>白人至上根深蒂固，有色人种被视为"劣等"。爱尔兰人在英格兰受排挤，犹太人遭商业抵制。</p>
                <p><strong>性别偏见：</strong>女性刚获投票权但仍被认为"天生软弱"。职业选择局限于教师、护士、打字员。</p>
                <p><strong>残疾歧视：</strong>战争伤残老兵沦为乞丐。精神病患被强制收容，接受脑叶切除"治疗"。</p>

                <h2>阶级鸿沟</h2>
                <p><strong>贵族特权：</strong>世袭爵位掌控土地与政治资源。私立学校、绅士俱乐部维持阶级壁垒。</p>
                <p><strong>新兴资产阶级：</strong>工厂主、银行家用金钱购买爵位。暴发户急于挤入上流社会但被老贵族鄙视。</p>
                <p><strong>中产困境：</strong>医生、律师、职员维持体面需透支收入。害怕跌落又难以晋升，最焦虑的夹心层。</p>
                <p><strong>工人阶级：</strong>十二小时工作制，全家老小挤在一间房。罢工遭镇压，工会领袖常"失踪"。</p>
                <p><strong>底层深渊：</strong>贫民窟如地狱，卖女为娼、童工、扒手是生存常态。慈善施粥处前排队者冻死街头。</p>

                <h2>饮歌镇货币体系</h2>
                <h3>基础货币单位</h3>
                <ul>
                    <li><strong>英镑（£）：</strong>主要货币单位</li>
                    <li><strong>先令（s）：</strong>1英镑 = 20先令</li>
                    <li><strong>便士（d）：</strong>1先令 = 12便士</li>
                </ul>

                <h3>日常消费（以先令计）</h3>
                <ul>
                    <li>啤酒：0.5先令</li>
                    <li>简餐：1先令</li>
                    <li>电车票：0.2先令</li>
                    <li>廉价旅店：2先令/晚</li>
                    <li>餐厅正餐：5先令</li>
                    <li>中档旅店：10先令/晚</li>
                </ul>

                <h3>工资水平（周薪）</h3>
                <ul>
                    <li>工人：30先令</li>
                    <li>技工：50先令</li>
                    <li>职员：80先令</li>
                    <li>专业人士：200先令</li>
                </ul>

                <h3>特殊交易</h3>
                <ul>
                    <li>黑市物品：价格翻倍</li>
                    <li>神秘物品：不收现金，以物易物。或价格高昂，有价无市</li>
                </ul>
            </div>

            <div class="page-nav">
                <button class="page-button page-prev" disabled>上一页</button>
                <button class="page-button page-next">下一页</button>
            </div>
        </div>

        <!-- 页面2: 神秘学介绍 -->
        <div id="page-2" class="page">
            <div class="lore-content">
                <h2>西方神秘学世界设定</h2>

                <h3>核心概述</h3>
                <p>神秘学(Occultism) - 1920年代秘密兴起的新兴学科，专门研究超自然现象与神秘侧存在。普通大众对其一无所知，仅在特定圈层内流传。</p>

                <h2>主要组织</h2>

                <h3>守序者 (The Wardens)</h3>
                <p><strong>性质：</strong>半官方神秘管理机构</p>
                <p><strong>结构：</strong>总部设于伦敦，分部遍布欧美主要城市，各分部独立运作，负责辖区内超自然事件</p>
                <p><strong>职能：</strong>调查处理神秘现象、逮捕超自然罪犯、收容控制危险神秘物品、掩盖真相，维持常态</p>

                <h3>知学会 (The Episteme Society)</h3>
                <p><strong>性质：</strong>学术研究组织</p>
                <p><strong>总部：</strong>英国伦敦</p>
                <p><strong>成员：</strong>学者、研究员、图书管理员</p>
                <p><strong>职能：</strong>神秘学理论研究、编撰神秘知识典籍、为守序者提供技术支持、培养新晋神秘学者</p>

                <h3>诡学会 (The Arcane Assembly)</h3>
                <p><strong>性质：</strong>地下激进组织</p>
                <p><strong>特征：</strong>完全独立于政府管控、成员遍布全球，身份隐秘、行事不择手段</p>
                <p><strong>资源：</strong>大量诡秘道具、失传秘法、古老圣物</p>
                <p><strong>宗旨：</strong>不惜一切代价探索神秘真相</p>

                <h3>新神会 (The New Divinity)</h3>
                <p><strong>性质：</strong>精英垄断集团</p>
                <p><strong>成员构成：</strong>世袭贵族、工业巨头、政界显要</p>
                <p><strong>核心理念：</strong>"知识即权力，权力属于配得上它的人。"他们认为普通人接触神秘知识只会带来灾难，唯有社会精英才有资格和能力掌控这些力量。</p>
                <p><strong>运作方式：</strong>知识垄断、技术管控、人才收割、血脉工程</p>

                <h3>升迁者 (The Ascendants)</h3>
                <p><strong>性质：</strong>超人类主义狂热教派</p>
                <p><strong>核心教义：</strong>"人类形态只是过渡，真正的进化在彼岸。"他们相信通过神秘学改造可以突破肉体凡躯，成为更高等的存在形式。</p>
                <p><strong>成员类型：</strong>原教旨派、融合派、实验体、诡人、共生者</p>
                <p><strong>改造实验：</strong>血肉重塑、意识扩张、灵魂分裂、维度嫁接</p>

                <h2>东方特殊性</h2>
                <h3>中国 - 神秘学宝库</h3>
                <p><strong>1920年代状况：</strong>国力衰落，内忧外患、传统文化遭受冲击、神秘知识散落民间</p>
                <p><strong>"法"的体系：</strong>完整的超自然力量体系、包含修炼、符咒、阵法等、西方神秘学相比之下残缺不全</p>

                <h2>西方神秘学困境</h2>
                <p><strong>残篇断章：</strong>大部分神秘典籍在中世纪猎巫运动中被焚毁，幸存文献多为手抄本的手抄本，错漏百出</p>
                <p><strong>语言障碍：</strong>古代文献使用失传语言（古苏美尔语、亚特兰蒂斯符文等），翻译全凭猜测</p>
                <p><strong>刻意隐晦：</strong>前人为防知识滥用，故意使用暗语、谜语记录，真意难辨</p>

                <h2>实践的危险性</h2>
                <p><strong>典型失败案例：</strong></p>
                <ul>
                    <li>伦敦迷雾事件：某贵族尝试召唤"晨雾精灵"，因咒语残缺召来维度裂隙，整个街区被异界迷雾吞噬</li>
                    <li>巴黎石化诅咒：炼金术士误解美杜莎之血配方，自己变成半石化怪物</li>
                    <li>柏林时间循环：学者试图重现时间魔法，导致整栋建筑陷入30天时间循环</li>
                </ul>

                <h2>神秘物品分级</h2>
                <ul>
                    <li><strong>安全级（Safe）：</strong>可控制，危害有限</li>
                    <li><strong>警戒级（Caution）：</strong>需特殊收容，有潜在危险</li>
                    <li><strong>危险级（Danger）：</strong>高度危险，需严格管控</li>
                    <li><strong>灾厄级（Catastrophe）：</strong>可能导致大规模伤亡</li>
                    <li><strong>末日级（Apocalypse）：</strong>威胁人类文明存续</li>
                </ul>
            </div>

